// Mode: Run Once for All Items
const rawInput = $input.all();
const nodeName = this.getNode?.()?.name || "H1-1";

// Extract neuron index (H1-1 -> index 0, H1-9 -> index 8)
const neuronMatch = nodeName.match(/(\d+)$/);
const neuronIdx = neuronMatch ? parseInt(neuronMatch[1], 10) - 1 : 0;

// Access trained weights from static data if available
let staticWeights = null;
try {
  staticWeights = $getWorkflowStaticData('global')?.weights;
} catch (e) {}

// Unfold incoming batch
let batch = [];
if (Array.isArray(rawInput[0]?.json?.body)) {
  batch = rawInput[0].json.body;
} else if (Array.isArray(rawInput[0]?.json)) {
  batch = rawInput[0].json;
} else {
  batch = rawInput.map(item => item.json.body || item.json);
}

// Fallback seed
let seed = 0;
for (let i = 0; i < nodeName.length; i++) {
  seed = (seed << 5) - seed + nodeName.charCodeAt(i);
  seed |= 0;
}

return batch.map((item, sampleIdx) => {
  const x = item.x || item.layerOutput || [];
  const inputDim = x.length;

  if (inputDim === 0) {
    return {
      json: {
        sampleIdx,
        neuron: nodeName,
        activation: 0
      }
    };
  }

  let z = 0;

  if (staticWeights?.W1 && staticWeights?.b1) {
    // 1. Use Trained Weights from Backprop
    z = staticWeights.b1[neuronIdx] ?? 0;
    for (let i = 0; i < inputDim; i++) {
      const w = staticWeights.W1[i]?.[neuronIdx] ?? 0;
      z += x[i] * w;
    }
  } else {
    // 2. Fallback to Deterministic Seed Formula
    const scale = Math.sqrt(2 / inputDim);
    const bias = Math.sin(seed * 0.73) * 0.05;
    z = bias;
    for (let i = 0; i < inputDim; i++) {
      const pseudoRand = Math.sin(seed * 1337 + i * 4999) * 10000;
      const w = (pseudoRand - Math.floor(pseudoRand) - 0.5) * 2 * scale;
      z += x[i] * w;
    }
  }

  return {
    json: {
      sampleIdx,
      neuron: nodeName,
      activation: Math.max(0, z)
    }
  };
});

