// Mode: Run Once for All Items
const items = $input.all();
const nodeName = this.getNode?.()?.name || "OUT-1";

const neuronMatch = nodeName.match(/(\d+)$/);
const neuronIdx = neuronMatch ? parseInt(neuronMatch[1], 10) - 1 : 0;

let staticWeights = null;
try {
  staticWeights = $getWorkflowStaticData('global')?.weights;
} catch (e) {}

let seed = 0;
for (let i = 0; i < nodeName.length; i++) {
  seed = (seed << 5) - seed + nodeName.charCodeAt(i);
  seed |= 0;
}

return items.map((item, sampleIdx) => {
  const x = item.json.layerOutput || item.json.x || [];
  const inputDim = x.length;

  let z = 0;

  if (staticWeights?.Wout && staticWeights?.bout) {
    z = staticWeights.bout[neuronIdx] ?? 0;
    for (let i = 0; i < inputDim; i++) {
      const w = staticWeights.Wout[i]?.[neuronIdx] ?? 0;
      z += x[i] * w;
    }
  } else {
    const scale = Math.sqrt(2 / (inputDim || 9));
    const bias = Math.sin(seed * 0.73) * 0.05;
    z = bias;
    for (let i = 0; i < inputDim; i++) {
      const pseudoRand = Math.sin(seed * 1337 + i * 4999) * 10000;
      const w = (pseudoRand - Math.floor(pseudoRand) - 0.5) * 2 * scale;
      z += x[i] * w;
    }
  }

  return {
    json: {
      sampleIdx,
      neuron: nodeName,
      zScore: z
    }
  };
});

