// Mode: Run Once for All Items
const items = $input.all();
const T = 0.1;

// Group logits by sample index
const sampleGroups = {};
for (const item of items) {
  const sIdx = item.json.sampleIdx ?? 0;
  if (!sampleGroups[sIdx]) sampleGroups[sIdx] = [];
  sampleGroups[sIdx].push(Number(item.json.zScore ?? 0));
}

return Object.keys(sampleGroups).map(sIdx => {
  const logits = sampleGroups[sIdx];
  const maxLogit = Math.max(...logits);
  const exps = logits.map(z => Math.exp((z - maxLogit) / T));
  const sumExps = exps.reduce((a, b) => a + b, 0);
  const probabilities = exps.map(e => Number((e / sumExps).toFixed(4)));
  const winningIndex = probabilities.indexOf(Math.max(...probabilities));

  return {
    json: {
      sampleIdx: Number(sIdx),
      logits,
      probabilities,
      predictedClass: `Class ${winningIndex + 1}`,
      confidence: `${(probabilities[winningIndex] * 100).toFixed(2)}%`,
      status: "COMPLETE"
    }
  };
});

